// GENERATED by scripts — a WebGPU compute shader that compiles Brainfuck and
// emits a WebAssembly module. Dispatch 1 compacts the source and checks bracket
// balance; dispatch 2 prefix-scans per-command byte lengths and has each lane
// write its opcode's fixed WebAssembly byte sequence at its scanned offset,
// while lane 0 writes the module header and code-section framing. Output is one
// module byte per u32 word. The instruction templates and header are the exact
// bytes verified byte-for-byte against the CPU compiler in this repo.

export const HEADER_BYTES = 91;
export const MAX_SOURCE_BYTES = 256;
/** Upper bound on emitted module size: header + framing + 256 * longest template. */
export const MAX_WASM_BYTES = 6755;

export const BRAINFUCK_WASM_WGSL = /* wgsl */ `
struct Params { source_len: u32, pad0: u32, pad1: u32, pad2: u32 };
struct Report { op_count: u32, wasm_len: u32, error: u32, pad: u32 };

@group(0) @binding(0) var<storage, read> source: array<u32>;
@group(0) @binding(1) var<uniform> params: Params;
@group(0) @binding(2) var<storage, read_write> ops: array<u32>;
@group(0) @binding(3) var<storage, read_write> wasm_out: array<u32>;
@group(0) @binding(4) var<storage, read_write> report: Report;

const HDR_LEN = 91u;
var<private> HDR: array<u32, 91> = array<u32, 91>(0u, 97u, 115u, 109u, 1u, 0u, 0u, 0u, 1u, 13u, 3u, 96u, 1u, 127u, 1u, 127u, 96u, 1u, 127u, 0u, 96u, 0u, 0u, 2u, 22u, 2u, 2u, 98u, 102u, 4u, 114u, 101u, 97u, 100u, 0u, 0u, 2u, 98u, 102u, 5u, 119u, 114u, 105u, 116u, 101u, 0u, 1u, 3u, 2u, 1u, 2u, 5u, 3u, 1u, 0u, 16u, 6u, 15u, 2u, 127u, 1u, 65u, 0u, 11u, 127u, 1u, 65u, 128u, 132u, 175u, 223u, 0u, 11u, 7u, 16u, 2u, 3u, 114u, 117u, 110u, 0u, 2u, 6u, 109u, 101u, 109u, 111u, 114u, 121u, 2u, 0u);
var<private> TPL: array<u32, 89> = array<u32, 89>(35u, 0u, 65u, 1u, 106u, 36u, 0u, 35u, 0u, 65u, 127u, 106u, 36u, 0u, 35u, 0u, 35u, 0u, 45u, 0u, 0u, 65u, 1u, 106u, 58u, 0u, 0u, 35u, 0u, 35u, 0u, 45u, 0u, 0u, 65u, 127u, 106u, 58u, 0u, 0u, 35u, 0u, 45u, 0u, 0u, 16u, 1u, 35u, 0u, 35u, 0u, 45u, 0u, 0u, 16u, 0u, 58u, 0u, 0u, 2u, 64u, 3u, 64u, 35u, 1u, 69u, 4u, 64u, 0u, 11u, 35u, 1u, 65u, 1u, 107u, 36u, 1u, 35u, 0u, 45u, 0u, 0u, 69u, 13u, 1u, 12u, 0u, 11u, 11u);
var<private> TPL_OFF: array<u32, 9> = array<u32, 9>(0u, 0u, 7u, 14u, 27u, 40u, 47u, 59u, 85u);
var<private> TPL_LEN: array<u32, 9> = array<u32, 9>(0u, 7u, 7u, 13u, 13u, 7u, 12u, 26u, 4u);

var<workgroup> scan_values: array<u32, 256>;
var<workgroup> scan_next: array<u32, 256>;
var<workgroup> bracket_stack: array<u32, 256>;
var<workgroup> code_start: u32;

fn decode(b: u32) -> u32 {
  switch b {
    case 62u { return 1u; }
    case 60u { return 2u; }
    case 43u { return 3u; }
    case 45u { return 4u; }
    case 46u { return 5u; }
    case 44u { return 6u; }
    case 91u { return 7u; }
    case 93u { return 8u; }
    default { return 0u; }
  }
}

fn scan_step(lane: u32, offset: u32) {
  var total = scan_values[lane];
  if (lane >= offset) { total += scan_values[lane - offset]; }
  scan_next[lane] = total;
  workgroupBarrier();
  scan_values[lane] = scan_next[lane];
  workgroupBarrier();
}

// Dispatch 1: classify, compact in source order, and check bracket balance.
@compute @workgroup_size(256)
fn compile_program(@builtin(local_invocation_index) lane: u32) {
  var byte = 0u;
  if (lane < params.source_len) { byte = source[lane]; }
  let op = decode(byte);
  scan_values[lane] = select(0u, 1u, op != 0u);
  if (lane == 0u) { report.op_count = 0u; report.wasm_len = 0u; report.error = 0u; }
  workgroupBarrier();

  scan_step(lane, 1u);
  scan_step(lane, 2u);
  scan_step(lane, 4u);
  scan_step(lane, 8u);
  scan_step(lane, 16u);
  scan_step(lane, 32u);
  scan_step(lane, 64u);
  scan_step(lane, 128u);

  if (op != 0u) { ops[scan_values[lane] - 1u] = op; }
  storageBarrier();

  if (lane == 0u) {
    let count = scan_values[255u];
    report.op_count = count;
    var depth = 0u;
    var i = 0u;
    loop {
      if (i >= count) { break; }
      let ins = ops[i];
      if (ins == 7u) {
        bracket_stack[depth] = i;
        depth += 1u;
      } else if (ins == 8u) {
        if (depth == 0u) { report.error = 1u; break; }
        depth -= 1u;
      }
      i += 1u;
    }
    if (report.error == 0u && depth != 0u) { report.error = 2u; }
  }
}

fn write_uleb(base: u32, v: u32) -> u32 {
  if (v < 128u) { wasm_out[base] = v; return 1u; }
  wasm_out[base] = (v & 0x7fu) | 0x80u;
  wasm_out[base + 1u] = v >> 7u;
  return 2u;
}

fn uleb_len(v: u32) -> u32 { if (v < 128u) { return 1u; } return 2u; }

// Dispatch 2: emit the WebAssembly module bytes, one byte per output word.
@compute @workgroup_size(256)
fn emit_wasm(@builtin(local_invocation_index) lane: u32) {
  let count = report.op_count;
  let err = report.error;
  var op = 0u;
  var len = 0u;
  if (lane < count) { op = ops[lane]; len = TPL_LEN[op]; }
  scan_values[lane] = len;
  workgroupBarrier();

  scan_step(lane, 1u);
  scan_step(lane, 2u);
  scan_step(lane, 4u);
  scan_step(lane, 8u);
  scan_step(lane, 16u);
  scan_step(lane, 32u);
  scan_step(lane, 64u);
  scan_step(lane, 128u);

  if (lane == 0u) {
    if (err == 0u) {
      let total = scan_values[255u];
      for (var h = 0u; h < HDR_LEN; h += 1u) { wasm_out[h] = HDR[h]; }
      var pos = HDR_LEN;
      let func_body_len = total + 2u;
      let code_vec_payload = uleb_len(func_body_len) + func_body_len;
      wasm_out[pos] = 10u;
      pos += 1u;
      pos += write_uleb(pos, 1u + code_vec_payload);
      wasm_out[pos] = 1u;
      pos += 1u;
      pos += write_uleb(pos, func_body_len);
      wasm_out[pos] = 0u;
      pos += 1u;
      code_start = pos;
      wasm_out[code_start + total] = 0x0bu;
      report.wasm_len = code_start + total + 1u;
    } else {
      report.wasm_len = 0u;
      code_start = 0u;
    }
  }
  workgroupBarrier();

  if (err == 0u && lane < count) {
    let base = code_start + (scan_values[lane] - len);
    let off = TPL_OFF[op];
    for (var k = 0u; k < len; k += 1u) { wasm_out[base + k] = TPL[off + k]; }
  }
}
`;
